/// Retains the `NSWindow.didUpdate` observer that keeps the title out of the title bar (issue #70).
private var titleVisibilityObserver: NSObjectProtocol?

deinit {
  for token in frameObservers { NotificationCenter.default.removeObserver(token) }
}

/// Only the active (last-key) window writes the shared sidebar prefs to UserDefaults, so multiple
/// windows don't clobber each other's selection / collapse / tab order; the single restored window
/// reads them on launch (issue #70, CQ1). `lastActiveStore` is modal-safe (a quit alert / Settings
/// becoming key never changes it). Defaults to `true` until the first window registers, so the
/// initial single window persists from the very first edit.
private var persistsSidebarPrefs: Bool {
  WindowRegistry.shared.lastActiveStore.map { $0 === self } ?? true
}

/// The list of configured projects — proxied to the shared `ProjectStore` so every window sees the
/// same list. (Storage moved out of `AppStore`; the get/set proxy keeps all existing call sites,
/// incl. `projects[i] = …` / `projects.removeAll`, working unchanged.)
var projects: [Project] {
  get { projectStore.projects }
  set { projectStore.projects = newValue }
}
@Published var selectedProjectID: Project.ID?
/// The selected terminal target — a `.root` or a `.workroom` (never `.project`), or nil
/// when nothing is selected (the launch state). `.project` is not a target; clicking a
/// project toggles its expansion instead. Persisted across launches (issue #14) via `didSet`
/// and restored in `apply()`.
@Published var selectedTargetID: SidebarID? {
  didSet {
    if persistsSidebarPrefs {
      Defaults[.sidebarSelection] = Self.targetIDString(for: selectedTargetID)
    }
    // The saved session records selection PER WINDOW (issue #46); the Defaults key above is the
    // single-slot cold-start fallback for a launch with no usable session file.
    markSessionDirty()
    // Promote this workroom in the quick switcher's most-recently-used order (issue #132).
    // UNCONDITIONAL, unlike the history record below: `applyLocation` raises `isNavigatingHistory`
    // for its whole body and the switcher commits through it, so a gated write would never record
    // where the switcher just took you — ⌥Tab would flip to the same place forever. Recency means
    // "where did the user end up", which is equally true of a ⌘[ replay.
    SwitcherRecency.shared.recordWorkroom(store: self, sid: selectedTargetID)
    // Record the new location for back/forward (issue #26), unless we're replaying history.
    if !isNavigatingHistory { recordCurrentLocation() }
    // Freshen the newly-selected workroom's status (incl. CI) — debounced so arrow-key
    // cycling through rows doesn't fork a probe per row (issue #24).
    scheduleSelectedStatusRefresh()
    // The inspector's section collapse/size is GLOBAL (issue #24) — deliberately NOT reloaded on a
    // workroom switch, so switching workrooms changes only the inspector's content, never its shape.
    // The Files tree is re-pointed lazily by `FilesPanel` (only while that section is shown), not
    // here — so selecting a workroom doesn't list its files unless you're actually browsing them.
    refreshSelectionHasTabs()  // the inspector follows the *active* (tab-having) selection
    // Re-point History the instant the workroom changes (only while it's the visible section,
    // mirroring HistoryPanel's own guard) so the list clears + shows its loader immediately,
    // instead of lingering on the previous workroom's commits until the panel's `.task` catches
    // up. `focus` is idempotent, so the panel's later re-focus to the same root no-ops.
    if selectedTargetID != oldValue {
      focusHistoryIfShown()
      focusRemoteStateIfShown()
      // A confirmation asking about the OLD workroom's dirty tree is meaningless once the selection
      // moves. `runRemoteAction` re-checks the sid so answering it couldn't misfire anyway, but leaving
      // the dialog up would ask about a workroom the user is no longer looking at.
      if pendingRemoteConfirm != nil { pendingRemoteConfirm = nil }
    }
  }
}

/// True while the selected target has ≥1 open tab. The inspector (History / Changes / Pull
/// Request) reflects the *active* workspace, so closing all tabs of the selected workroom empties
/// it even though the sidebar row stays selected (the detail pane likewise drops to its "No
/// terminal" placeholder — this keeps the two in sync). Maintained at selection changes + the tab
/// add/remove hooks: a plain `terminals.tabCount` read in a view wouldn't re-render on a tab close,
/// because AppStore doesn't forward `terminals`' `objectWillChange` (only `ProjectStore`'s).
@Published private(set) var selectionHasTabs = false
/// Project paths the user has collapsed in the sidebar (issue #14). Held here as `@Published`
/// rather than read via `@Default` in the view: a `@Default` change does not reliably re-evaluate
/// the sidebar's `List` until some *other* state changes (e.g. the pointer moving over a row), so
/// expand/collapse appeared to "stick" until you moved the mouse. `@Published` fires
/// `objectWillChange` synchronously, so the tree updates on the click itself. Persisted via `didSet`.
@Published var collapsedProjects: Set<String> = Defaults[.collapsedProjects] {
  didSet { if persistsSidebarPrefs { Defaults[.collapsedProjects] = collapsedProjects } }
}
/// Remembered workroom tab-bar order (issue #23), as `TerminalTarget.ID` strings. `@Published`
/// (not read via `@Default` in the view) because a `@Default` write doesn't reliably re-render the
/// `NavigationSplitView` detail, so a drag-reorder's write didn't take and the dropped chip snapped
/// back to its old slot. Persisted via `didSet`; initialised from `Defaults`. Stale ids resolve away
/// in `orderedWorkroomTargets`, so it's self-healing.
@Published var workroomTabOrder: [TerminalTarget.ID] = Defaults[.workroomTabOrder] {
  didSet { if persistsSidebarPrefs { Defaults[.workroomTabOrder] = workroomTabOrder } }
}
/// Whether the projects sidebar column is visible. The single source of truth for showing the
/// custom `SidebarColumn` *and* the View ▸ Projects checkmark — a bare AppKit `toggleSidebar` has no
/// state a menu checkmark can bind to, so it could never show a tick. Session-only (resets to shown
/// on launch); the dragged width is persisted separately to `Defaults.sidebarWidth`.
@Published var sidebarVisible: Bool = true
/// Whether a collapsed sidebar is *temporarily* on screen via edge-hover reveal (issue #56): the
/// left Projects overlay (`previewingLeft`) and the right inspector overlay (`previewingRight`).
/// These are observable app state, not view-local, because other surfaces must react: notification
/// routing flashes the row instead of popping a toast while `previewingRight` (so the revealed
/// Notifications panel and a toast never co-display — the invariant at `recordNotification`), and
/// `ToastStack` withholds toasts while it's set. Session-only and deliberately NOT persisted (a
/// transient hover state). Set by `EdgeRevealSidebar`.
@Published var previewingLeft: Bool = false
@Published var previewingRight: Bool = false
/// The cursor is over the matching sidebar's title-bar *toggle button* while that sidebar is
/// collapsed — the trigger for the edge-hover reveal (issue #74). The trigger used to be a wide
/// strip over the toolbar (issue #56), but that strip sat directly above the leftmost workroom
/// tabs: reaching for a tab tripped the reveal, whose panel then covered the very tab you wanted.
/// Pinning the trigger to the toggle button itself keeps it clear of the tabs. `hoveringLeftToggle`
/// is set by the leading sidebar's title-bar toggle (`LeadingTitlebarBar`); the trailing side has no
/// toggle button (the activity bar is always pinned to that edge), so `hoveringRightToggle` stays
/// false. Observed by `EdgeRevealSidebar`. Session-only, not persisted (transient hover state).
@Published var hoveringLeftToggle: Bool = false
@Published var hoveringRightToggle: Bool = false
/// The docked Projects sidebar's chosen width, set by `SidebarColumn`'s resize handle on drag-end
/// (mirrors `dockedInspectorWidth`), so the edge-hover reveal panel (issue #56) matches the user's
/// width rather than a fixed guess. `nil` until first set this session; both the column and the
/// reveal fall back to `Defaults.sidebarWidth`. Session-only; not `@Published` — the live drag is
/// tracked in the column's local state and only committed here once, on drag-end.
var dockedSidebarWidth: CGFloat?
/// The docked right inspector's width (issue #56), set by the custom inspector column's resize
/// handle and read by both the docked card and the right edge-hover reveal. `@Published` so a
/// resize drag re-renders the inspector live. Safe to publish (unlike `dockedSidebarWidth`):
/// the inspector is a custom column now, not the native NavigationSplitView one, so nothing writes
/// this on every layout pass. `nil` until first set this session; falls back to `Defaults`.
@Published var dockedInspectorWidth: CGFloat?
/// The workroom-into-workroom split groups (issue #23 follow-up): each entry is two+ workrooms shown
/// side by side, every one a full `TargetTerminalDetail`. Empty = the single `selectedTarget` (the
/// normal case). Leaves are `SidebarID`; the focused member IS `selectedTargetID`. **Several groups can
/// coexist** — grouping two solo workrooms leaves the other groups alone — and they're disjoint (a
/// workroom is in at most one) with ≥2 leaves each (a lone leaf is "no split", mirroring the
/// terminal-split invariant). At most one group is *visible*: the one holding the selection.
/// Persisted with the rest of the session (issue #46) as target-id strings; a group whose leaves no
/// longer resolve dissolves on restore. All edits go through the helpers in
/// `AppStore+WorkroomSplit.swift`; stale leaves resolve away in `resolvedSplitLeaves(of:)`, so it's
/// self-healing. See that file for the transforms.
@Published var workroomSplits: [PaneLayout<SidebarID>] = [] {
  didSet { markSessionDirty() }
}
/// Terminal targets whose terminal subtree is *expanded* in the sidebar (issue #30). Inverse
/// polarity to `collapsedProjects`: terminals are collapsed by default, so the set holds only the
/// expanded ones (empty = all collapsed). Persisted with the session (issue #46) — restored only for
/// targets whose panes actually came back, since an expand flag pointing at nothing would render an
/// empty disclosure. Pruned below 2 tabs by the `onTabsRemoved` hook in `init`.
@Published var expandedTerminalTargets: Set<TerminalTarget.ID> = [] {
  didSet { markSessionDirty() }
}
/// Per-project resolved root branch/bookmark labels, hydrated asynchronously after each
/// load (see `resolveBranches`). Absent ⇒ the root row shows a dim "root" until resolved.
var rootRefs: [Project.ID: RootRef] {
  get { projectStore.rootRefs }
  set { projectStore.rootRefs = newValue }
}
/// Per-workroom (and per-root) VCS + CI status driving the ambient badges and the Changes
/// detail panel (issue #24), keyed by `SidebarID`. Resolved app-side (see
/// `WorkroomStatusResolver`), best-effort/"last checked" — NOT real-time. Ephemeral:
/// deliberately NOT persisted (operational state, unlike the sidebar prefs above). Hydrated
/// after each load, on selection, and on focus; see `AppStore+WorkroomStatus.swift`.
var workroomStatuses: [SidebarID: WorkroomStatus] {
  get { projectStore.workroomStatuses }
  set { projectStore.workroomStatuses = newValue }
}
/// Whether the GitHub CLI is usable for the PR/CI probes (machine-global). Optimistic default so
/// no warning flashes before the first check; refreshed by `refreshGitHubCLI()` and read by the
/// Pull Request inspector section. Drives a warning + gates the `gh` probes when not available.
var githubCLIStatus: GitHubCLIStatus {
  get { projectStore.githubCLIStatus }
  set { projectStore.githubCLIStatus = newValue }
}
/// Owns the `gh auth status` verdict's freshness and single-flight (see `GitHubAuthCache`). The
/// timestamp that used to live here is gone: two owners for one truth is how the staleness gate and
/// the write drifted apart in the first place.
var ghAuthCache: GitHubAuthCache { projectStore.ghAuthCache }
var vcsToolVersionCache: VCSToolVersionCache { projectStore.vcsToolVersionCache }
/// A PR write action (Phase 2b) is running — disables the PR actions menu so it can't double-fire.
@Published var prActionInFlight = false

/// The commit sheet's target, or nil when it's closed. Presented from the Changes section header.
///
/// The sheet owns its own draft and selection for its lifetime, which is most of why it is a sheet:
/// a per-workroom draft store on the AppStore would need pruning on workroom delete, would inherit
/// a recycled workroom name's old message, and — since `AppStore` is per WINDOW — would let two
/// windows on the same workroom fight over one `Defaults` dictionary with last-writer-wins.
@Published var pendingCommit: PendingCommit?

/// Rows with a commit in flight. A `Set` rather than a `Bool` because the app's premise is N
/// parallel workrooms: a single flag would let a commit in one disable the button in another.
/// Read by `isCommitting`. Lives on the shared `ProjectStore` — see its doc for why per-window
/// was wrong.
var committingTargets: Set<SidebarID> {
  get { projectStore.committingTargets }
  set { projectStore.committingTargets = newValue }
}

/// In-flight commit counts per project root, which is the granularity the status lanes must respect.
var committingProjectRoots: [String: Int] {
  get { projectStore.committingProjectRoots }
  set { projectStore.committingProjectRoots = newValue }
}

/// In-flight write (commit/fetch/push/pull) counts per project root — see `ProjectStore`'s doc.
var writingProjectRoots: [String: Int] {
  get { projectStore.writingProjectRoots }
  set { projectStore.writingProjectRoots = newValue }
}

// Inspector section collapse (issue #24). Held on the store rather than as `@Default` in the
// inspector view: the `.inspector` content doesn't observe `@Default` changes, but it DOES observe
// this `@EnvironmentObject`. These are the *live* state for the currently selected workroom;
// they're the GLOBAL layout, loaded once at launch and persisted on every change to
// `Defaults[.inspectorLayout]` via `loadInspectorState()` / `persistInspectorState()` — shared
// across all workrooms, so a workroom switch never changes them.
@Published var changesSectionCollapsed = false {
  didSet { persistInspectorState() }
}
/// Collapse state of the Files section (the repo file tree). Sits second, right under Changes.
@Published var filesSectionCollapsed = false {
  didSet { persistInspectorState() }
}
@Published var prSectionCollapsed = false {
  didSet { persistInspectorState() }
}
/// Collapse state of the History section (the commit log) — the middle section of the Changes
/// stack, between Changes and Pull Request.
@Published var historySectionCollapsed = false {
  didSet {
    persistInspectorState()
    // Expanding it with a workroom already selected: point the model now (same reason the
    // section-switch didSet does) so the pane shows its loader instead of the `.idle` placeholder
    // until `HistoryPanel`'s `.task` catches up. `focus` is idempotent, so this only does work when
    // the selection MOVED while the section was shut (the selection didSet skips its focus then).
    //
    // `isLoadingInspectorState` guards this the same way it guards the persist above, for the other
    // direction: `loadInspectorState()` runs inside `init` and would otherwise fire a real VCS read
    // from a didSet during construction. It happens to be inert today (`inspectorTarget` is nil until
    // a selection has tabs) — the guard is what stops that accident from becoming load-bearing.
    if !isLoadingInspectorState, !historySectionCollapsed { focusHistoryIfShown() }
  }
}
/// Whether the History section is on screen: its pane is the active one and the section isn't
/// collapsed. The gate for every History load trigger (the eager focuses via `focusHistoryIfShown`,
/// the live watcher refresh, the app-refocus safety net, and `HistoryPanel`'s own activation task) —
/// a collapsed or swapped-out section must not run VCS reads for a log nobody can see.
var historySectionShown: Bool {
  activeInspectorSection.subSections.contains(.history) && !historySectionCollapsed
}
/// Point History's model at the inspector's active target, but only when that log is genuinely on
/// screen: the section shown AND the inspector open.
///
/// The visibility half matters because History lives in the DEFAULT pane now. A `focus` is not a
/// cheap "point at" — it runs a full page read (`HistoryModel.load` → `VCSProviding.log`, which for
/// git is a repo open, a 101-commit revwalk, a ref enumeration and an unpushed-range walk), so
/// without this gate every selection change would read a repo for a pane nobody can see, for every
/// user, in the shipped default state.
///
/// Nothing has to re-trigger this when the inspector opens: `RootView` builds `InspectorColumn`
/// inside `if showInspector`, so opening it CONSTRUCTS `HistoryPanel`, whose `.task` calls
/// `HistoryModel.activate` — the same load, at the moment it's first worth doing.
private func focusHistoryIfShown() {
  guard inspectorIsVisible, historySectionShown else { return }
  commitHistory.focus(inspectorTarget.map { URL(fileURLWithPath: $0.path) })
}

/// Whether the VCS toolbar is on screen. It sits above the section stack rather than inside a
/// section, so only the activity section matters — not a collapse flag.
var remoteToolbarShown: Bool { activeInspectorSection == .changes }

/// Point the toolbar's model at the inspector's active target, but only when it's genuinely visible.
///
/// Same gate, and the same reason, as `focusHistoryIfShown`: a `focus` here is not a cheap pointer
/// move but two or three `git`/`jj` processes, so without this every selection change would read a
/// repo for a toolbar nobody can see.
private func focusRemoteStateIfShown() {
  guard inspectorIsVisible, remoteToolbarShown else {
    remoteState.focus(nil)
    return
  }
  remoteState.focus(remoteTarget())
}

/// The toolbar's target, resolved from the inspector's active target. `nil` when nothing statusable
/// is selected, or when the target's project has gone away.
///
/// A `.project` row is deliberately not statusable — it's the collapsible header, not a working copy —
/// so it resolves to nil and the toolbar shows its "no workroom selected" state.
func remoteTarget() -> RemoteStateModel.Target? {
  guard let sid = inspectorTargetID else { return nil }
  let projectPath: String
  let path: String
  switch sid {
  case .project:
    return nil
  case .root(let p):
    projectPath = p
    path = p
  case .workroom(let p, let name):
    guard let project = projects.first(where: { $0.path == p }),
      let workroom = project.workrooms.first(where: { $0.name == name })
    else { return nil }
    projectPath = p

/// Whether the global ⌘§ show/hide hotkey is registered (issue #13).
static let globalHotkey = Key<Bool>("globalHotkeyEnabled", default: true)

/// Bundle id of the editor for ⌘-clicked file paths; "" = the file's default app.
static let filePathEditor = Key<String>("filePathEditorBundleID", default: "")

/// Bundle id of the last editor picked from the toolbar "Open in…" menu; "" = none yet.
static let lastEditor = Key<String>("openInEditorBundleID", default: "")

/// Whether the right-hand inspector (Changes / Files / Pull Request) is open. The stored key is
/// still `showNotificationsInspector` for back-compat — the inspector used to carry a Notifications
/// section (moved to the left sidebar, issue #118), but the persisted user state is preserved.
static let showInspector = Key<Bool>("showNotificationsInspector", default: false)

/// The selected top-level section in the right activity bar (the vertical icon rail), so it reopens
/// where you left it. Stored as the bare raw string via `ActivitySection: PreferRawRepresentable`;
/// a stored value matching no case falls back to `.changes`. Which *pane* the inspector shows;
/// whether the pane is visible at all is `showInspector`.
static let activeInspectorSection = Key<ActivitySection>(
  "inspector.activeSection", default: .changes)

/// Inline terminal agent (issue #49): always on — a failed command can be diagnosed by the local
/// `claude`/`codex` CLI and a fix suggested in the pane's status bar. (No enable toggle; automatic
/// vs manual diagnosis is `terminalAgentAutoDiagnose`.)
/// When on, an eligible failure diagnoses automatically; otherwise the status bar waits for a click.
/// Set the first time the user accepts the "auto-diagnose next time?" prompt.
static let terminalAgentAutoDiagnose = Key<Bool>("terminalAgentAutoDiagnose", default: false)
/// Whether the one-time "auto-diagnose from now on?" prompt has been shown (after the first manual
/// Diagnose). Prevents re-asking on every manual diagnosis.
static let terminalAgentAutoDiagnosePrompted = Key<Bool>(
  "terminalAgentAutoDiagnosePrompted", default: false)
/// Mask common secret shapes in captured output before it's sent to the agent. On by default.
static let terminalAgentRedactSecrets = Key<Bool>("terminalAgentRedactSecrets", default: true)
/// Preferred agent backend: "auto" (claude, else codex), "claude", or "codex".
static let terminalAgentBackend = Key<String>("terminalAgentBackend", default: "auto")
/// Model for the inline (no-tools) diagnosis. A fast, cheap model is plenty for a bounded
/// error diagnosis and avoids the user's default (often Opus) running on every failure. Empty =
/// let the CLI pick its default. (Issue #49 cost optimisation.)
static let terminalAgentModel = Key<String>(
  "terminalAgentModel", default: "claude-haiku-4-5-20251001")

/// The docked right inspector's remembered column width. `.inspector` resets to its `ideal`
/// width every time it's re-shown, so we feed this back as the ideal — hiding and re-showing
/// (and relaunching) restores the user's last width instead of snapping back to 300. Written
/// from the live width measurement, clamped to the `.inspectorColumnWidth` min/max range.
static let inspectorWidth = Key<Double>("inspector.width", default: 300)

/// The docked Projects sidebar's remembered column width. The sidebar is a custom resizable column
/// (`SidebarColumn`, not `NavigationSplitView`'s native one), so its width is persisted here and
/// fed back on launch — mirrors `inspectorWidth`. Clamped to the column's min/max when applied.
static let sidebarWidth = Key<Double>("sidebar.width", default: 270)

/// Whether the notifications menu bar item is shown (issue #33). On by default.
static let showMenuBarItem = Key<Bool>("showMenuBarItem", default: true)

/// Load remote author/reviewer avatars — Gravatar (by commit-author email) and
/// `github.com/<login>.png`. On by default. Off ⇒ only the coloured initials chip renders and NO
/// avatar image request is made, so opening an untrusted repo's History never beacons the viewer's
/// IP + an author-email hash to gravatar.com. A privacy control (issue #59 review); the initials
/// fallback is always the same one used for unknown/404 avatars, so nothing else changes.
static let loadRemoteAvatars = Key<Bool>("loadRemoteAvatars", default: true)

/// The persisted selected sidebar target as a `TerminalTarget.ID` string, or nil (issue #14).
static let sidebarSelection = Key<String?>("sidebar.selectionTargetID", default: nil)

/// The last-viewed pane in the Settings window (⌘,), so it reopens where you left it (macOS
/// System Settings behaviour). Stored as the bare raw string via `SettingsPane:
/// PreferRawRepresentable`; a stored value matching no case falls back to `.general`.
static let settingsSelectedPane = Key<SettingsPane>("settings.selectedPane", default: .general)

/// The last window's frame as `NSStringFromRect` (issue #70). The launch window restores it so it
/// reopens at the size you left; empty means "use the default size". The value-based `WindowGroup`
/// doesn't restore window size itself, so it's managed app-side in `AppStore.attachWindow`.
static let mainWindowFrame = Key<String>("window.mainFrame", default: "")

/// Project paths the user has collapsed in the sidebar; absence of a path means expanded
/// (the default). Persisted natively as a string array (issue #14).
static let collapsedProjects = Key<Set<String>>("sidebar.collapsedProjects", default: [])

/// Per-project "Run command" config, keyed by the project's absolute path (issue #7). Absence of a
/// path means no run command configured. A single path-keyed map (mirrors `collapsedProjects`):
/// `Defaults` keys are static, so per-project keys aren't an option.
static let runCommands = Key<[String: RunConfig]>("runCommands", default: [:])

/// Remembered order of the workroom tab bar, as `TerminalTarget.ID` strings (issue #23, same
/// encoding as `sidebarSelection`). Terminals now DO survive a relaunch (issue #46), but this stays
/// an ordering hint applied to whatever is currently active — stale ids resolve away harmlessly.
static let workroomTabOrder = Key<[String]>("workroomsView.tabOrder", default: [])

/// Trigger modifiers for the two quick switchers (issue #132): ⌥Tab steps open workrooms across
/// every window, ⌃Tab steps the current workroom's panes. Retunable because a global hotkey grabber
/// beats our local key monitor and cannot be detected — AltTab, HyperSwitch and Contexts all take
/// ⌥Tab by default via a CGEvent tap, so for those users the default is unreachable and a different
/// modifier is the only fix. No Settings UI yet; `SwitcherModifier` owns the offered set.
static let switcherWorkroomModifier = Key<SwitcherModifier>(
  "switcher.workroomModifier", default: .option)
static let switcherPaneModifier = Key<SwitcherModifier>(
  "switcher.paneModifier", default: .control)

/// When Workroom itself last fetched a project, keyed by the project's absolute path (fetch always
/// runs at the project root, so this is per-project, never per-workroom). Path-keyed map for the
/// same reason as `runCommands`.
///
/// **Exists because of a jj asymmetry, not for convenience.** git writes `FETCH_HEAD` on *every*
/// fetch, so its mtime is a complete record and this map adds nothing for a git project. jj's fetch
/// is invisible: it passes `--no-write-fetch-head`, and a fetch that brings nothing prints
/// "Nothing changed." and records **no operation at all** (verified, jj 0.43) — so the op-log scan
/// alone would mean "last fetch that changed something", and a user clicking Fetch with nothing new
/// would watch a stale timestamp not move.
///
/// `RemoteStateModel` therefore reports `max(backend evidence, this)`. The backend still wins when
/// it's newer, which is what keeps a `jj git fetch` run in the user's own terminal visible.
static let vcsLastFetch = Key<[String: Date]>("vcs.lastFetch", default: [:])

/// Global inspector layout (issue #24): which of the inspector's sections are collapsed and the
/// relative heights of the panes, ordered as `InspectorSectionKind.allCases` — Changes, Files, Pull
/// Request, History. That is NOT the on-screen order (the Changes pane stacks Changes → History →
/// Pull Request); it's the canonical `storeIndex` order, and the vector is four unnamed bools, so
/// the two must not be confused. Shared across ALL workrooms and windows — switching the selected
/// workroom changes the inspector's *content* but never its section collapse/size (a single global
/// shape, not per-workroom). A stored layout whose entry count doesn't match the current section
/// count is discarded to the default on load. (Was a per-workroom map keyed by `targetIDString`; a
/// new key string means old per-workroom data is simply ignored.)
///
/// `.v2` because History moved *into* the Changes stack: the entry count didn't change (History
/// already held index 3 as a solo pane), so the count check couldn't catch it, yet the stored
/// weights are meaningless for the new stack — a machine that had dragged the Changes/Pull Request
/// divider carries a never-dragged weight of 1 for History and would open it squeezed to its floor.
/// The rename discards those once, so the three sections start at equal heights.
static let inspectorLayout = Key<InspectorPaneState>(
  "inspector.layout.v2", default: .default)

/// The app `CFBundleShortVersionString` whose release notes the user has already seen (issue: What's
/// New). nil on a fresh install / first launch after this feature shipped — recorded silently with
/// no historical backfill. The What's-New dialog shows only when the running version is newer.
static let lastSeenVersion = Key<String?>("app.lastSeenVersion", default: nil)

/// Bounded-retry bookkeeping for the auto What's-New fetch (so a firewalled machine doesn't fire a
/// doomed GitHub request every launch forever). `whatsNewAttemptVersion` is the version those
/// attempts were for; the count resets when the running version changes. After
/// `WhatsNewService.maxAutoAttempts` failures the auto fetch gives up (the menu item still works).
static let whatsNewAttemptVersion = Key<String?>("app.whatsNewAttemptVersion", default: nil)
static let whatsNewAttempts = Key<Int>("app.whatsNewAttempts", default: 0)

/// Diff viewer layout (issue #66): `.unified` (default) or `.sideBySide`. Read by `DiffViewer` at
/// view-construct time, so the choice applies to newly opened diff tabs (a narrow pane falls back
/// to unified regardless). Stored as the bare raw string via `DiffViewMode: PreferRawRepresentable`.
static let diffViewMode = Key<DiffViewMode>("diffViewMode", default: .unified)

/// Per-workroom display label (issue #41), keyed by the workroom's `targetIDString`

import AppKit
import Defaults
import SwiftUI

struct RootView: View {
  @EnvironmentObject var store: AppStore
  @EnvironmentObject var notifications: NotificationCenterStore
  // Observed so the detail's workroom tab bar re-renders as terminals open/close (a tab appears when a
  // workroom gains its first terminal and disappears when it loses its last) — issue #23.
  @EnvironmentObject var terminals: TerminalSessions
  // Drives the leading title-bar "Update" pill (injected into the accessory closure below) and the
  // "What's New" dialog. Both injected by `WorkroomApp` on the `RootWindow`.
  @EnvironmentObject var updater: Updater
  @EnvironmentObject var whatsNew: WhatsNewService
  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  /// Drives the title-bar accessory's dim while a dialog is up, matched to `DialogOverlay`'s backdrop.
  @Environment(\.colorScheme) private var colorScheme
  @Default(.theme) private var theme
  /// Whether the right-hand inspector (Changes / Files / Pull Request) is open. `@Default` (not
  /// `@State`) so the View-menu command (WorkroomCommands) toggles the same value.
  @Default(.showInspector) private var showInspector

  /// Drives the New Project sheet — set from `store.requestAddProject`, which both the menu command
  /// and the sidebar's Add-Project buttons raise. Hosted here (vs the sidebar) so the command presents
  /// it even if the sidebar is collapsed via the standard toggle. The sheet (issue #103) offers two
  /// modes: add an existing repo, or create + git-init a new directory.
  @State private var showAddProject = false

  /// Presents the keyboard-shortcuts reference, raised by the `Keyboard Shortcuts…` command via
  /// notification (a menu command can't anchor a sheet).
  @State private var showKeyboardShortcuts = false

  /// The "What's New" dialog's content, or nil when closed. Set by the launch-window auto-check.
  /// Window-local so multiple windows never stack duplicate dialogs.
  @State private var whatsNewContent: WhatsNewSheetContent?

  /// Live preview of a workroom tab being dragged into the detail content to form a split (issue #23
  /// follow-up). Set by `WorkroomTabBar`'s drag, read by `WorkroomSplitView` to highlight the drop edge.
  @State private var workroomChipDrag: WorkroomPaneDrag?
  /// The detail content area's global frame, so a chip drag can be resolved against the workroom panes.
  @State private var detailContentFrame: CGRect = .zero

  /// True when the selected target can host a terminal right now: it exists, isn't missing, and the
  /// detail isn't currently showing the creating slot's loader/setup dialog (issue #116).
  private var terminalInteractionAvailable: Bool {
    guard let target = store.selectedTarget, !target.isMissing else { return false }
    if store.isCreationFocused { return false }
    return true
  }

  var body: some View {
    // The custom chrome lives in a full-width `.left` titlebar accessory (`accessoryBarContent`, hosted
    // via `TitlebarAccessoryHost` in `rootWindowChrome`), not a content top-strip and not SwiftUI
    // `.toolbar` items — so AppKit owns the bar height (an empty NSToolbar; see WindowBackgroundThemer)
    // and centers the traffic lights alongside the controls.
    // `rootModals` sits OUTSIDE `rootReveals` so the command-palette dialogs — which are `.overlay`s,
    // not sheets — render above the toast stack and above an edge-revealed sidebar. Inside, an
    // arriving toast drew on top of the dialog. Only the overlay presenters care about this ordering;
    // `.sheet` / `.alert` are position-independent.
    rootWindowChrome(rootLifecycle(rootModals(rootReveals(splitView))))
  }

  /// The full title-bar bar hosted in the `.left` titlebar accessory: leading controls, the workroom
  /// tab strip (fills + scrolls), trailing controls. Environment objects are re-injected because the
  /// accessory is a separate hosting tree from the main window content.
  private var accessoryBarContent: some View {
    HStack(spacing: 6) {
      LeadingTitlebarBar()
      workroomTabsBar
      TrailingTitlebarBar()
    }
    .padding(.horizontal, WorkroomTitlebar.outerInset)
    .frame(maxWidth: .infinity, maxHeight: .infinity)
    // No own background — the accessory is transparent so the window's panel bg shows through it AND
    // behind the traffic lights uniformly (an opaque fill here didn't match the titlebar strip behind
    // the lights). WindowBackgroundThemer sets the window bg to the panel token.
    .environmentObject(store)
    .environmentObject(notifications)
    .environmentObject(terminals)
    .environmentObject(updater)
    // The accessory is a window-level AppKit hosting tree, so the dialog's own backdrop — an overlay
    // on the content below — can never cover it. Left alone, the workroom tab strip's New/Open buttons
    // and its chips stay clickable through a "modal" dialog, and the bar stays undimmed while
    // everything beneath it darkens. Both halves read the same opacity + curve from
    // `DialogOverlayStyle` so they can't drift.
    .disabled(store.activePicker != nil)
    .overlay {
      Color.black
        .opacity(
          store.activePicker != nil ? DialogOverlayStyle.backdropOpacity(for: colorScheme) : 0
        )
        .allowsHitTesting(false)
    }
    .animation(
      reduceMotion ? nil : DialogOverlayStyle.revealAnimation, value: store.activePicker != nil)
  }

  private var workroomTabsBar: some View {
    // ALWAYS mounted, even with no tabs: its trailing Open/New buttons are how you get your first
    // workroom open in a fresh window, so they can't be gated on a tab already existing. (It also
    // hosts the provisional "Creating…" chip before any tab resolves — issue #116.) With an empty
    // run the bar is just those two buttons over the draggable title bar.
    WorkroomTabBar(
      tabs: store.displayedWorkroomTargets(), selectedID: store.selectedTargetID,
      onSelect: { selectWorkroomTab($0) },
      chipPaneDrag: $workroomChipDrag,
      localize: { workroomChipLocal($0) },
      dropTarget: { workroomChipDropTarget(at: $0) }
    )
    .frame(maxWidth: .infinity)
  }

  /// The two-column `NavigationSplitView` core (sidebar + detail/inspector). The window chrome, modal
  /// presentations, and lifecycle hooks layer on in `body` via the `root*` helpers below — each its own
  /// function so the modifier chain type-checks within the compiler's budget. The fully-inline chain
  /// timed out the type-checker on CI ("unable to type-check this expression in reasonable time"); this
  /// is the same split-it-up reason `EdgeRevealSidebars`/`MenuStateValues`/`NewWorkroomPresenter` exist.
  private var splitView: some View {
    // A hand-rolled split (sidebar | detail | inspector) instead of `NavigationSplitView`: the native
    // sidebar column drew an inset card with a ~30pt top toolbar-reserve that left an empty gap under
    // the custom title bar, and that inset isn't controllable. `SidebarColumn`/`InspectorColumn` are
    // our own resizable cards (same `sidebarCard` as the edge-reveal, so pinned == unpinned), giving
    // full control over their position. Visibility round-trips through `store.sidebarVisible` /
    // `showInspector` (the View-menu ticks + toggles); width persists per column to `Defaults`.
    // A *detail-only* NavigationSplitView: we keep it (vs a plain HStack) only for the window
    // toolbar/layering context it sets up — that's what lets the custom title bar, drawn in the
    // full-size content under the native title bar, render crisp instead of washed-out by the
    // title-bar vibrancy (a plain HStack / NavigationStack doesn't). Its native sidebar column is
    // never used (forced `.detailOnly`) — that column is what kept the ~30pt inset-card top gap — so
    // the real sidebar is our own `SidebarColumn` in the detail HStack, flush below the bar.
    // Wrapped in a *detail-only* `NavigationSplitView` (empty sidebar column, forced `.detailOnly`) —
    // NOT a plain HStack. A plain HStack detail in a full-size-content window with a visible `.unified`
    // toolbar loses SwiftUI `.onHover` for its content that sits near the top under the title bar (the
    // terminal tab strip's trailing toolbar buttons never lit their hover well — issue #114); the
    // title-bar region eats mouse-moved for a raw content view. `NavigationSplitView` hosts the detail
    // in an `NSSplitViewController`, which sets up the correct content tracking so `.onHover` fires
    // again. Dropping it (0e354d6e) was to stop it clipping `.toolbar { items }` to the sidebar-column
    // width — but the chrome no longer lives in toolbar items; it's a full-width window-level `.left`
    // `TitlebarAccessoryHost` (see `accessoryBarContent`), which NavigationSplitView does not clip. So
    // we get correct hover back with no clipping. The empty native sidebar column is unused — the real
    // sidebar is our own `SidebarColumn` in the detail HStack, flush below the bar.
    NavigationSplitView(columnVisibility: .constant(.detailOnly)) {
      Color.clear.frame(width: 0)
    } detail: {
      HStack(spacing: 0) {
        if store.sidebarVisible {
          SidebarColumn(
            paneDrag: $workroomChipDrag,
            localize: { workroomChipLocal($0) },
            dropTarget: { workroomChipDropTarget(at: $0) }
          )
          .transition(.move(edge: .leading))
        }
        detail
          .frame(maxWidth: .infinity, maxHeight: .infinity)
        if showInspector {
          InspectorColumn()
            .transition(.move(edge: .trailing))
        }
        // The activity bar is ALWAYS present, flush to the window's trailing edge — the inspector
        // content pane (above) slides in/out beside it. Placed inside the detail-only
        // NavigationSplitView so its icon buttons get working `.onHover` (issue #114).
        ActivityBar()
      }
      .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: store.sidebarVisible)
      .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: showInspector)
    }
  }

  /// Error alert, add-project importer, and the new-workroom / workroom-delete / project-delete

